Matching Ayahs
- = Alif, Lám, Mím. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Ti jsou na správném vedení od svého Pána a ti jsou úspěšní. 2:5; 31:5
- = Děti Izraele, připomeňte si mou milost, kterou jsem vám prokázal, a že jsem vás vyvýšil nad lidstvo veškeré. 2:47; 2:122
- = To byl národ, který již pominul. Dostane se mu, co si vysloužil, a vám se dostane, co jste si vysloužili. A nebudete tázáni na to, co oni dělali. 2:134; 2:141
- = V něm (pekle) budou navěky; trest jim nebude zmírněn a nebude jim dána oddech. 2:162; 3:88
- = Výjimkou jsou ti, kteří se poté kajícně obrátí a napraví. Vždyť Bůh je odpouštějící, slitovný. 3:89; 24:5
- = Ti, kdo neuvěřili a naše znamení za lež prohlašovali, ti budou obyvateli pekla. 5:10; 5:86
- = A nepřijde jim žádné znamení od jejich Pána, aniž by se od něho odvrátili. 6:4; 36:46
- = A byli zesměšňováni poslové již před tebou, však ty, kdož se jim posmívali, obklopilo to, čemu se posmívali. 6:10; 21:41
- = Rci: "Bojím se, neposlechnu-li svého Pána, trestu dne velikého." 6:15; 39:13
- = A postihlo je zemětřesení a nazítří leželi v domech svých mrtví, tvářemi k zemi. 7:78; 7:91
- = I vrhl hůl svou, a hle, byl to zjevný had. 7:107; 26:32
- = I vytáhl ruku svou, a hle, byla bílá pro ty, kdož na ni hledí. 7:108; 26:33
- = I řekli: "Uvěřili jsme v Pána lidstva veškerého." 7:121; 26:47
- = Pána Mojžíšova a Árónova. 7:122; 26:48
- = A já jim odklad dám. Vždyť lest má je pevná. 7:183; 68:45
- = On je ten, jenž poslal svého posla s vedením správným a s náboženstvím pravdy, aby je povýšil nad veškerá náboženství, i když se to protiví mnohobožcům. 9:33; 61:9
- = Proroku, bojuj proti nevěřícím a pokrytcům a buď přísný k nim! Jejich útočištěm bude peklo a jak hnusný je to cíl! 9:73; 66:9
- = A říkají: "Kdy splní se tento slib, jste-li pravdomluvní?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = A poslali jsme Mojžíše se znameními svými a zjevnou mocí. 11:96; 40:23
- = A dali jsme Mojžíšovi Písmo, ale byli o něm v rozporu. A kdyby nebylo slova, jež předcházelo od tvého Pána, bylo by mezi nimi rozhodnuto. A oni jsou ohledně něho v hlubokých pochybnostech. 11:110; 41:45
- = To není Bohu nijak těžké. 14:20; 35:17
- = A až jej vytvořím a vdechnu do něho ducha svého, padněte před ním na zem klaníce se!" 15:29; 38:72
- = I padli andělé všichni jednohlasně na zem. 15:30; 38:73
- = (Bůh) řekl: "Vyjdi odtud, jsi zahnán." 15:34; 38:77
- = (Iblís) řekl: "Pane můj, dej mi odklad do dne, kdy budou vzkříšeni." 15:36; 38:79
- = (Bůh) řekl: "Budiž ti odklad dán." 15:37; 38:80
- = Do dne lhůty známé." 15:38; 38:81
- = Kromě služebníků tvých upřímných. 15:40; 38:83
- = A bohabojní budou v zahradách a u pramenů. 15:45; 51:15
- = I řekl: "A jaká je vaše záležitost, poslové?" 15:57; 51:31
- = I řekli: "Byli jsme vysláni k lidu provinilému." 15:58; 51:32
- = Ti, kdož uvěřili a nepotřísnili svou víru nespravedlností – ti budou v bezpečí a ti jsou správně vedeni. 16:42; 29:59
- = Ať zpychnou nad tím, co jsme jim dali. Užívejte si, však záhy se dozvíte! 16:55; 30:34
- = Potom šel cestou (jinou). 18:89; 18:92
- = Jdi k Faraónovi, nebot přestoupil všechny meze." 20:24; 79:17
- = A ti, kdož pohlavní údy své střeží. 23:5; 70:29
- = Kromě manželek svých a těch, jichž zmocnila se pravice jejich, a nebudou za to pokáráni. 23:6; 70:30
- = Však ti, kdož více než toto vyhledávají, ti přestupují meze. 23:7; 70:31
- = A ti, kdož svěřené povinnosti a smlouvy své dodržují. 23:8; 70:32
- = (Noe) řekl: "Pane můj, pomoz mi, nebot oni mě za lháře prohlašují." 23:26; 23:39
- = Tá, Sín, Mím. 26:1; 28:1
- = Toto jsou znamení Písma zjevného. 26:2; 28:2
- = V tom je věru znamení, však většina z nich nevěří. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = A Pán tvůj je dozajista mocný a slitovný. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = A potom jsme ony druhé utopili. 26:66; 37:82
- = Já jsem pro vás poslem důvěryhodným. 26:107; 26:125; 26:143; 26:162; 26:178
- = Bojte se Boha a poslouchejte mne! 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = A nežádám od vás za to odměnu, vždyť odměna má náleží jen Pánu lidstva veškerého. 26:109; 26:127; 26:145; 26:164; 26:180
- = V zahradách a u pramenů. 26:147; 44:52
- = I řekli: "Ty zajisté jsi jen očarovaný!" 26:153; 26:185
- = Kromě jeho ženy, o níž bylo předurčeno, že bude mezi opozdilými. 26:171; 37:135
- = Pak jsme ony druhé zničili. 26:172; 37:136
- = A dali jsme na ně déšť (kamenů) a jak zlý to déšť pro varované! 26:173; 27:58
- = Což chtějí urychlit náš trest? 26:204; 37:176
- = Ti, kdož modlitbu vykonávají a almužnu dávají a pevně věří v život posmrtný. 27:3; 31:4
- = A (pamatuj) na den, kdy je zavolá a řekne: "Kde jsou ti, jež jste mi přidružovali?" 28:62; 28:74
- = A naši předkové? 37:17; 56:48
- = I přiblíží se jeden k druhému a budou se vyptávat. 37:27; 52:25
- = Kromě upřímných služebníků Božích. 37:40; 37:74; 37:128; 37:160
- = V zahradách slastí. 37:43; 56:12
- = A zanechali jsme pro něj (památku) mezi potomky: 37:78; 37:108; 37:129
- = Takto odměňujeme ty, kdož dobro konají. 37:80; 37:121; 37:131; 77:44
- = Nebot on byl z našich věřících služebníků. 37:81; 37:111; 37:132
- = Co je vám, že tak soudíte? 37:154; 68:36
- = To není nic jiného než připomínka lidstvu. 38:87; 81:27
- = Seslání Knihy od Boha mocného, moudrého. 39:1; 45:2; 46:2
- = Há, Mím. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Při Knize zjevné! 43:2; 44:2
- = Nech je tedy, ať si planě hovoří a hrají, až se setkají se svým dnem, který jim je slibován. 43:83; 70:42
- = (Bude jim řečeno): "Jezte a pijte v bezpečí v odměnu za to, co jste činili." 52:19; 77:43
- = Žádáš od nich snad odměnu, takže by byli zadluženi? 52:40; 68:46
- = Mají snad vědomosti o skrytém, takže je mohou zapisovat? 52:41; 68:47
- = A jak kruté bylo mé potrestání a mé varování! 54:16; 54:21; 54:30
- = A učinili jsme Korán snadným k zapamatování. Je někdo, kdo si připomene? 54:17; 54:22; 54:32; 54:40
- = Které z dobrodiní Pána svého chcete popírat? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Skupina z prvních. 56:13; 56:39
- = A byli jsme zbaveni? 56:67; 68:27
- = Veleb jméno Pána svého největšího! 56:74; 56:96; 69:52
- = To je seslání od Pána lidstva veškerého. 56:80; 69:43
- = Chválí Boha všechno na nebesích a všechno na zemi a on mocný je i moudrý. 59:1; 61:1
- = Když jsou mu přednášeny naše verše, říká: "Povídačky starých!" 68:15; 83:13
- = Vždyť on bude v životě spokojeném. 69:21; 101:7
- = V zahradě vysoké. 69:22; 88:10
- = A nepobízí k nakrmení chudáka. 69:34; 107:3
- = To je věru řeč posla vznešeného. 69:40; 81:19
- = Toto je připomenutí. A kdo chce, ať si zvolí cestu k Pánu svému. 73:19; 76:29
- = Kdo chce, ať si to připomene. 74:55; 80:12
- = Běda v ten den těm, kdož lháři nazývali! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = Spravedliví věru budou v blaženosti. 82:13; 83:22
- = Je to kniha popsaná. 83:9; 83:20
