- Ti, kdož jsou na nebesích, a ti, kdož jsou na zemi, leda koho Allah chce. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
