- Přišlo ti z vědění, nemáš od Allaha ani ochránce ani. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
